function safeNodes(graph: number[][]): number[] {
  const n = graph.length;
  const color = new Array(n).fill(0); // 0 new, 1 on path or unsafe, 2 safe
  for (let s = 0; s < n; s++) {
    if (color[s] !== 0) continue;
    // iterative DFS: stack of [node, next edge index]
    const stack: number[][] = [[s, 0]];
    color[s] = 1;
    while (stack.length) {
      const top = stack[stack.length - 1];
      const u = top[0];
      if (top[1] < graph[u].length) {
        const v = graph[u][top[1]++];
        if (color[v] === 0) { color[v] = 1; stack.push([v, 0]); }
        else if (color[v] === 1) { stack.length = 0; } // cycle: leave every node on the path at 1
      } else {
        color[u] = 2;
        stack.pop();
      }
    }
  }
  const out: number[] = [];
  for (let i = 0; i < n; i++) if (color[i] === 2) out.push(i);
  return out;
}

