class Solution:
    def safeNodes(self, graph: List[List[int]]) -> List[int]:
        n = len(graph)
        color = [0] * n  # 0 new, 1 on path or unsafe, 2 safe
        for s in range(n):
            if color[s]:
                continue
            stack = [[s, 0]]
            color[s] = 1
            while stack:
                top = stack[-1]
                u = top[0]
                if top[1] < len(graph[u]):
                    v = graph[u][top[1]]
                    top[1] += 1
                    if color[v] == 0:
                        color[v] = 1
                        stack.append([v, 0])
                    elif color[v] == 1:
                        stack.clear()  # cycle: every node on the path stays unsafe
                else:
                    color[u] = 2
                    stack.pop()
        return [i for i in range(n) if color[i] == 2]

