function safeNodes(graph: number[][]): number[] {
  const n = graph.length;
  const rev: number[][] = Array.from({ length: n }, () => []);
  const out = new Array(n).fill(0);
  for (let i = 0; i < n; i++) {
    out[i] = graph[i].length;
    for (const j of graph[i]) rev[j].push(i);
  }
  const safe = new Array(n).fill(false);
  const queue: number[] = [];
  for (let i = 0; i < n; i++) if (out[i] === 0) { safe[i] = true; queue.push(i); }
  for (let h = 0; h < queue.length; h++) {
    for (const i of rev[queue[h]]) {
      if (--out[i] === 0) { safe[i] = true; queue.push(i); }
    }
  }
  const res: number[] = [];
  for (let i = 0; i < n; i++) if (safe[i]) res.push(i);
  return res;
}

