        n = len(graph)
        rev = [[] for _ in range(n)]
        out = [len(e) for e in graph]
        for i, edges in enumerate(graph):
            for j in edges:
                rev[j].append(i)
        safe = [False] * n
        queue = deque(i for i in range(n) if out[i] == 0)
        for i in queue:
            safe[i] = True
        while queue:
            j = queue.popleft()
            for i in rev[j]:
                out[i] -= 1
                if out[i] == 0:
                    safe[i] = True
                    queue.append(i)
        return [i for i in range(n) if safe[i]]

